import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
def cols(t): return [c[1] for c in con.execute(f'PRAGMA table_info("{t}")')]
for t in ['gaps','adversarial_findings','determination_gates','observed_terms','term_adjudications','decisions','parameter_declinations']:
    print(t, cols(t))
print("gaps.status:", con.execute("select status,count(*) from gaps group by 1").fetchall() if 'status' in cols('gaps') else 'n/a')
for c in cols('adversarial_findings'):
    if c in ('verdict','status','disposition','outcome','severity','repair_status'):
        print("adv."+c, con.execute(f'select "{c}",count(*) from adversarial_findings group by 1').fetchall())
print("determination_gates:", con.execute("select * from determination_gates").fetchall())
print("observed_terms unadjudicated:", con.execute("select count(*) from observed_terms o where not exists (select 1 from term_adjudications a where a.observed_id=o.observed_id)").fetchone() if 'observed_id' in cols('observed_terms') else cols('observed_terms'))
print("--- owner-ish columns anywhere")
for (t,) in con.execute("select name from sqlite_master where type='table'"):
    for c in cols(t):
        if any(k in c.lower() for k in ('approv','owner','ruling','warrant','reviewed_by','decided','rationale','reason')):
            print(f"  {t}.{c}")
PY

