import sys, sqlite3
sys.path.insert(0,'scripts')
import dbcore
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
hits=[]; closed=0; shape=0
for (t,) in con.execute("select name from sqlite_master where type='table' and name!='sqlite_sequence'"):
    for c in [r[1] for r in con.execute(f'PRAGMA table_info("{t}")')]:
        try: v = dbcore.check_values(con, t, c)
        except Exception as e: v = None
        if v:
            closed += 1
            own = [x for x in v if 'OWNER' in str(x).upper()]
            for x in own:
                n = con.execute(f'select count(*) from "{t}" where "{c}"=?', (x,)).fetchone()[0]
                hits.append((t,c,x,n))
print("closed IN-list columns:", closed)
for h in hits: print(h)
PY

