const { chromium } = require('playwright');
const fs = require('fs');
const S = process.argv[2];
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 400, height: 800 } });
  const logs = [];
  page.on('console', m => logs.push('console.' + m.type() + ': ' + m.text()));
  page.on('pageerror', e => logs.push('pageerror: ' + e.message));
  await page.route('https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/sql-wasm.js', r =>
    r.fulfill({ status: 200, contentType: 'application/javascript', body: fs.readFileSync(S + '/sqljs-dl/sql-wasm.js') }));
  await page.goto('file://' + S + '/spike/index.html');
  await page.waitForSelector('html[data-spike-done="1"]', { timeout: 60000 });
  const rows = await page.$$eval('.row', els => els.map(e => e.innerText.replace(/\n/g, ' | ')));
  console.log(await page.$eval('#banner', e => e.textContent));
  rows.forEach(r => console.log(' ', r));
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth);
  console.log('horizontal overflow at 400px:', overflow);
  logs.forEach(l => console.log(l));
  await browser.close();
})().catch(e => { console.error('TEST ERROR', e.message); process.exit(1); });
JS
