const { chromium } = require('playwright'); const fs = require('fs');
const P = process.argv[2], S = process.argv[3];
(async () => {
  const b = await chromium.launch();
  for (const scheme of ['light', 'dark']) {
    const ctx = await b.newContext({ viewport: { width: 400, height: 860 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2, colorScheme: scheme });
    const page = await ctx.newPage();
    await page.route('https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/sql-wasm.js', r => r.fulfill({ status: 200, contentType: 'application/javascript', body: fs.readFileSync(S + '/sqljs-dl/sql-wasm.js') }));
    await page.route('https://fonts.googleapis.com/**', r => r.fulfill({ status: 200, contentType: 'text/css', body: '' }));
    await page.goto('file://' + P); await page.waitForSelector('html[data-ready]');
    await page.screenshot({ path: `${S}/ob-test/shots/${scheme}-home.png` });
    if (scheme === 'light') {
      await page.goto('file://' + P + '#waiting'); await page.waitForFunction(() => document.querySelector('h1').textContent === 'Waiting on you'); await page.screenshot({ path: `${S}/ob-test/shots/light-waiting.png` });
      await page.goto('file://' + P + '#t-search-candidates'); await page.waitForFunction(() => document.querySelector('h1') && document.querySelector('h1').textContent === 'search_candidates'); await page.waitForSelector('#rows .card'); await page.screenshot({ path: `${S}/ob-test/shots/light-table.png` });
      await page.click('#rows a.card >> nth=0'); await page.waitForFunction(() => location.hash.startsWith('#r-search-candidates-') && document.querySelector('.kv details')); await page.screenshot({ path: `${S}/ob-test/shots/light-row.png` });
    }
    await ctx.close();
  }
  await b.close();
})();
JS
