const AUDIT = /(^|_)(created|updated|raised|resolved)_(at|by_session)$|_session$/;
const defaultFields = (t) => t.cols.filter((c) => !c.pk && !AUDIT.test(c.name)).slice(0, 4).map((c) => c.name);

// ---------- pieces ----------
function value(v, full) {
  if (isNil(v)) return h("span", { class: "nil" }, "—");
  if (typeof v === "string" && /^[\[{]/.test(v.trim())) {
    try { const j = JSON.parse(v); if (full) return h("pre", null, JSON.stringify(j, null, 2)); } catch (e) { /* plain text */ }
  }
  const s = String(v);
  return full || s.length <= 120 ? s : s.slice(0, 120).trimEnd() + "…";
}

input.new_string:
const AUDIT = /(^|_)(created|updated|raised|resolved)_(at|by_session)$|_session$/;
// The fields a card shows by default, chosen from the data: the most text-like column that is mostly filled (the
// row's label), then the next three filled columns in table order. The owner can change them per table.
function defaultFields(t) {
  const rows = all("select * from " + q(t.name) + " limit 100");
  const use = t.cols.filter((c) => !c.pk && !AUDIT.test(c.name)).map((c) => {
    const vals = rows.map((r) => r[c.name]).filter((v) => !isNil(v));
    return { name: c.name, filled: rows.length ? vals.length / rows.length : 0, len: vals.length ? vals.reduce((a, v) => a + String(v).length, 0) / vals.length : 0 };
  }).filter((c) => c.filled >= 0.5);
  const label = use.filter((c) => c.len <= 300).sort((a, b) => b.len - a.len)[0];
  return [...(label ? [label.name] : []), ...use.filter((c) => c !== label).slice(0, 3).map((c) => c.name)];
}
const fill = (el, kids) => el.replaceChildren(...kids.flat().filter((k) => k != null && k !== false));

// ---------- pieces ----------
// lim: true shows the whole value; a number caps it; the default is 120 characters.
function value(v, lim = 120) {
  if (isNil(v)) return h("span", { class: "nil" }, "—");
  if (typeof v === "string" && /^[\[{]/.test(v.trim())) {
    try { const j = JSON.parse(v); if (lim === true) return h("pre", null, JSON.stringify(j, null, 2)); } catch (e) { /* plain text */ }
  }
  const s = String(v);
  return lim === true || s.length <= lim ? s : s.slice(0, lim).trimEnd() + "…";
}

