@@ -0,0 +1,451 @@
+<title>Guidebook Data Browser</title>
+<meta name="claude:viewport-fit-sides" content="cover">
+<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;600&family=IBM+Plex+Sans:wght@400;600&display=swap">
+<style>
+/* Layout: phone first. One column; a list opens a card; a card opens a row. Nothing depends on hover or a wide grid. */
+:root {
+  --bg: #f2f5f4;
+  --panel: #ffffff;
+  --ink: #16201c;
+  --muted: #566861;
+  --rule: #d3dcd9;
+  --chip: #e4ecea;
+  --accent: #1b5c87;
+  --accent-ink: #ffffff;
+  --warn-bg: #fbf0d4;
+  --warn-ink: #6b4500;
+  --bad: #9c2f1d;
+  --sans: "IBM Plex Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
+  --mono: "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;
+}
+@media (prefers-color-scheme: dark) {
+  :root:not([data-theme="light"]) {
+    --bg: #0f1614; --panel: #172120; --ink: #e2eae6; --muted: #92a49c; --rule: #2a3835;
+    --chip: #22302d; --accent: #78b9e4; --accent-ink: #0b1a22; --warn-bg: #3a2f10; --warn-ink: #f0d9a0;
+    --bad: #f2917d; color-scheme: dark;
+  }
+}
+:root[data-theme="dark"] {
+  --bg: #0f1614; --panel: #172120; --ink: #e2eae6; --muted: #92a49c; --rule: #2a3835;
+  --chip: #22302d; --accent: #78b9e4; --accent-ink: #0b1a22; --warn-bg: #3a2f10; --warn-ink: #f0d9a0;
+  --bad: #f2917d; color-scheme: dark;
+}
+* { box-sizing: border-box; }
+body {
+  background: var(--bg); color: var(--ink); font: 16px/1.5 var(--sans);
+  padding-block: 0 48px;
+  padding-left: max(16px, env(safe-area-inset-left, 0px));
+  padding-right: max(16px, env(safe-area-inset-right, 0px));
+}
+body::before { content: ""; position: fixed; inset: 0 0 auto; height: env(safe-area-inset-top, 0px); z-index: 20; background: var(--bg); }
+.wrap { max-width: 720px; margin: 0 auto; }
+a { color: var(--accent); }
+h1, h2, h3 { margin: 0; text-wrap: balance; line-height: 1.25; }
+h1 { font-size: 1.35rem; }
+h2 { font-size: 0.8rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); font-weight: 600; }
+h3 { font-size: 1rem; }
+p { margin: 0; }
+code, .mono { font-family: var(--mono); font-size: 0.86em; overflow-wrap: anywhere; }
+button, input, select { font: inherit; color: inherit; }
+button, .btn { min-height: 44px; padding: 0 14px; border: 1px solid var(--rule); border-radius: 6px; background: var(--panel); cursor: pointer; }
+button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, summary:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
+input[type=search], select { min-height: 44px; width: 100%; padding: 0 12px; border: 1px solid var(--rule); border-radius: 6px; background: var(--panel); }
+#bar { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 10; background: var(--bg); border-bottom: 1px solid var(--rule); margin: 0 calc(-1 * max(16px, env(safe-area-inset-left, 0px))) 16px; padding: 8px max(16px, env(safe-area-inset-left, 0px)); }
+#bar .in { max-width: 720px; margin: 0 auto; display: grid; gap: 6px; }
+#bar .top { display: flex; align-items: center; gap: 8px; min-width: 0; }
+#bar .top .ttl { flex: 1; min-width: 0; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
+#bar nav { display: flex; gap: 8px; }
+#bar nav a { flex: 1; min-height: 40px; display: flex; align-items: center; justify-content: center; border-radius: 6px; text-decoration: none; background: var(--chip); color: var(--ink); font-weight: 600; font-size: 0.9rem; }
+#bar nav a[aria-current=page] { background: var(--accent); color: var(--accent-ink); }
+main { display: grid; gap: 20px; }
+.stack { display: grid; gap: 8px; }
+.card, .item { display: grid; gap: 4px; padding: 12px 14px; min-height: 44px; border: 1px solid var(--rule); border-radius: 6px; background: var(--panel); color: var(--ink); text-decoration: none; min-width: 0; }
