+    --chip: #22302d; --accent: #78b9e4; --accent-ink: #0b1a22; --warn-bg: #3a2f10; --warn-ink: #f0d9a0;
+    --bad: #f2917d; color-scheme: dark;
+  }
+}
+:root[data-theme="dark"] {
