+function notFound(what) { return [h("div", { class: "stack" }, h("h1", null, "Not found"), h("p", { class: "gl" }, "There is no " + what + " in this copy of the database."), h("a", { href: "#stages" }, "Back to the tables"))]; }
+
+// ---------- routing ----------
+function route() {
+  const hash = location.hash.slice(1) || "stages";
+  let page, title = "Guidebook Data Browser";
+  try {
+    if (hash === "stages") page = homePage();
+    else if (hash === "waiting") { page = waitingPage(); title = "Waiting on you"; }
+    else if (hash.startsWith("t-")) { title = unslug(hash.slice(2)); page = tablePage(title); }
+    else if (hash.startsWith("v-")) { title = unslug(hash.slice(2)); page = viewPage(title); }
+    else if (hash.startsWith("r-")) { const i = hash.lastIndexOf("-"); title = unslug(hash.slice(2, i)); page = rowPage(title, Number(hash.slice(i + 1))); }
+    else page = notFound(hash);
+  } catch (e) { page = [h("p", { class: "err" }, "This page failed to open: " + ((e && e.message) || e))]; }
+  document.getElementById("main").replaceChildren(...page.flat().filter(Boolean));
+  document.getElementById("ttl").textContent = title;
+  document.getElementById("back").hidden = hash === "stages";
