+document.getElementById("back").addEventListener("click", () => { if (history.length > 1) history.back(); else location.hash = "stages"; });
+
+(async function boot() {
+  try {
+    const SQL = await window.initSqlJs({ wasmBinary: b64(WASM_B64) });
