+    h("div", { class: "stack" }, h("h1", null, "Waiting on you"),
+      h("p", { class: "gl" }, "Each item is a question with the context needed to answer it. Tap one to open it, choose an option, and add your words where the option asks. An answer saved here is not a ruling until Claude writes it into the ledger in your words, so tell Claude to record your answers."),
+      h("p", { class: "ok", id: "answered" })),
+    words,
+    group("Decisions that hold up building", "The workplan names these six as the ones that gate building.", META.decisions.filter((d) => d.gates).map(dprompt)),
+    group("Other decisions on the plan", "Each has a recommended answer from the report, except where none is recorded. The plan follows the recommendation unless you answer otherwise.", META.decisions.filter((d) => !d.gates).map(dprompt)),
+    ...queueRows().map(({ e, rows }) => group(e.title, e.why, rows.length
+      ? rows.map((r) => promptCard({ key: e.id + "-" + r.id, tag: e.table + " " + r.id, title: r.label, question: e.question, why: e.why_yours, options: e.options, body: rowContext(e, r.id) }))
+      : [h("p", { class: "gl" }, "Nothing waiting.")])),
+  ];
+  setTimeout(updateCounts, 0);
+  return page;
+}
+function notFound(what) { return [h("div", { class: "stack" }, h("h1", null, "Not found"), h("p", { class: "gl" }, "There is no " + what + " in this copy of the database."), h("a", { href: "#stages" }, "Back to the tables"))]; }
+
+// ---------- routing ----------
+function route() {
+  const hash = location.hash.slice(1) || "stages";
+  let page, title = "Guidebook Data Browser";
+  try {
+    if (hash === "stages") page = homePage();
+    else if (hash === "waiting") { page = waitingPage(); title = "Waiting on you"; }
+    else if (hash.startsWith("t-")) { title = unslug(hash.slice(2)); page = tablePage(title); }
+    else if (hash.startsWith("v-")) { title = unslug(hash.slice(2)); page = viewPage(title); }
+    else if (hash.startsWith("r-")) { const i = hash.lastIndexOf("-"); title = unslug(hash.slice(2, i)); page = rowPage(title, Number(hash.slice(i + 1))); }
+    else page = notFound(hash);
+  } catch (e) { page = [h("p", { class: "err" }, "This page failed to open: " + ((e && e.message) || e))]; }
+  document.getElementById("main").replaceChildren(...page.flat().filter(Boolean));
+  document.getElementById("ttl").textContent = title;
+  document.getElementById("back").hidden = hash === "stages";
+  document.getElementById("nav-stages").setAttribute("aria-current", hash === "waiting" ? "false" : "page");
+  document.getElementById("nav-waiting").setAttribute("aria-current", hash === "waiting" ? "page" : "false");
+  window.scrollTo(0, 0);
+}
+document.getElementById("back").addEventListener("click", () => { if (history.length > 1) history.back(); else location.hash = "stages"; });
+
+(async function boot() {
+  try {
+    const SQL = await window.initSqlJs({ wasmBinary: b64(WASM_B64) });
+    db = new SQL.Database(b64(DB_B64));
+    SCHEMA = loadSchema();
+    await loadAnswers();
+    updateCounts();
+    window.addEventListener("hashchange", route);
+    route();
+    document.documentElement.setAttribute("data-ready", "1");
+  } catch (e) {
+    document.getElementById("main").replaceChildren(h("p", { class: "err" }, "The database could not be opened here: " + ((e && e.message) || e)));
+    document.documentElement.setAttribute("data-ready", "error");
+  }
+})();
+</script>

