t="scripts/generate/owner_browser.html"; h=open(t,encoding="utf-8").read()
a=h[h.index("// A row the ledger already rules on"):h.index("const openDecisions")]
b='''// A row the ledger already rules on leaves the open list and is shown with the ruling (the queue entry's `ruled` map).
// The ruled list is read from the map, not from the query, so a card stays once the row has left the query's results.
const queueRows = () => META.queue.map((e) => {
  const got = all(e.sql), ruled = e.ruled || {};
  return { e, rows: got.filter((r) => !ruled[String(r.id)]),
    ruled: Object.keys(ruled).map((id) => ({ id, label: (got.find((r) => String(r.id) === id) || {}).label || "Row " + id })) };
});
'''
h=h.replace(a,b,1); open(t,"w",encoding="utf-8").write(h); print("ok")
